; Bane v2: Bane with a dispersal opening, for CellHack2.  GENERATED by cells/gen_bane2.py -- do not edit by hand.
; Written with AI help.
;
; Paste this whole file into the site.  It has no org/bits/section/%include on purpose: the server
; prepends `bits 64 / org CODE_BASE / default rel / <cellhack.inc>` and runs `nasm -f bin`.
; CPU target: plain qemu64 (SSE2 only used; no VEX).  No loops, no stack use.  Relies on: rax = 0 at entry
; (registers are reset before every call).  The cell memory is addressed as [abs CELLMEM_BASE + n].
;
; Memory: [0] bearing 0..3, [1] steps left, [2] and [3] the stored bite, [4..7] x | y << 16 of the square this cell last split from.
; A child copies the memory; a cell with steps left that is not on that square is a walker.
;
; Behaviour
;   0. Stored bite: the square I bit last time still holds an enemy: bite it again (4 instructions, no view scan).
;   1. Otherwise an enemy next to me: bite it and store the bite (memory [2] square, [3] action): 16.
;   2. Refill: an empty neighbour with an enemy beside or beyond it: split into it when energy >= 12.
;      Any other empty neighbour: split when energy >= 16 (first of DOWN, RIGHT, UP, LEFT).
;   3. An empty neighbour, below those energies, an enemy anywhere in the 5x5: stop walking; rest (the prey hold;
;      from tick 2980: split when energy >= 5).
;   4. An empty neighbour, no enemy in the 5x5:
;      walker: MOVE along the bearing while that square is empty and steps are left; otherwise settle.
;      settled, energy >= 5: split.  The first child from this square goes forward (my bearing) and walks 8
;      squares; later children go to the next empty square clockwise from the last one and walk 2
;      (8 before tick 0).  Energy < 5: rest.
;   5. No empty neighbour: Bane's boxed block (feed a friend that has an empty neighbour, or the poorest friend).
;
; Instruction counts per path (every executed instruction, including taken jumps and ret):
;   stored bite 4, first bite 16, refill 16, split e >= 16 16, boxed block: Bane's + 5
;   enemy in the 5x5: rest e < 5 31, late split 31, hold 33
;   walker move 39; walker blocked, e < 5 41
;   settled, e < 5: rest 33 (35 for a cell with steps left on its own square)
;   first child forward 43; other children 47 to 66

start:
	movzx		ecx, byte [abs CELLMEM_BASE + 2]	; stored bite: view offset of the square (0 = none)
	cmp		byte [rdi + rcx + 24], CELL_ENEMY
	mov		al, [abs CELLMEM_BASE + 3]
	je		EXIT_ADDR			; the enemy is still there: bite in 4 instructions
	movdqu		xmm0, [rdi + VIEW_CELLS + VIEW_UP]	; view idx 7..22
	pcmpeqb		xmm0, [kEnemy]
	pmovmskb	ecx, xmm0			; bits 0 UP, 4 LEFT, 6 RIGHT, 10 DOWN
	mov		al, [abs bite_tbl + rcx]	; eat action, 0 = no enemy
	test		al, al
	jnz		setlock				; bite, and store it for the next tick

slow:						; 10 instructions so far
	movdqu		xmm1, [rdi + VIEW_CELLS + 6]	; view idx 6..21
	pcmpeqb		xmm1, [kRefill]			; empty neighbours, enemies beside/beyond them
	pmovmskb	ecx, xmm1			; mask 0..7607
	mov		al, [abs act_tbl + rcx]		; split to take (0 = no empty neighbour)
	cmp		sil, [abs thr_tbl + rcx]	; energy it needs (12 refill, 16 other, 255 boxed)
	jae		EXIT_ADDR			; refill / split: 11 instructions
	test		al, al
	jz		boxed
	movdqu		xmm1, [rdi + VIEW_CELLS]	; view idx 0..15
	movdqu		xmm2, [rdi + VIEW_CELLS + 9]	; view idx 9..24
	pcmpeqb		xmm1, [kTwoLo]			; lane 12 (self) never matches
	pcmpeqb		xmm2, [kTwoHi]			; lane 3 (self) never matches
	por		xmm1, xmm2
	pmovmskb	r8d, xmm1
	test		r8d, r8d
	jnz		threat				; an enemy in the 5x5 (26 so far)
	mov		ecx, [rdi + VIEW_X]		; x | y << 16
	cmp		byte [abs CELLMEM_BASE + 1], 0
	je		settled
	cmp		ecx, [abs CELLMEM_BASE + 4]
	je		settled				; on the square I split from: not a walker
	movzx		r9d, byte [abs CELLMEM_BASE + 0]
	and		r9d, 3
	movzx		r10d, byte [abs dir_idx + r9]
	cmp		byte [rdi + VIEW_CELLS + r10], CELL_EMPTY
	jne		walk_end			; blocked
	dec		byte [abs CELLMEM_BASE + 1]
	lea		eax, [r9 + ACT_MOVE]
	ret					; walker move: 39
walk_end:
	mov		byte [abs CELLMEM_BASE + 1], 0
settled:
	cmp		esi, 5
	jb		rest
	movzx		r9d, byte [abs CELLMEM_BASE + 0]
	and		r9d, 3
	cmp		ecx, [abs CELLMEM_BASE + 4]
	je		rotate				; not the first child from this square
	movzx		r10d, byte [abs dir_idx + r9]
	cmp		byte [rdi + VIEW_CELLS + r10], CELL_EMPTY
	je		emit_long			; first child: forward
rotate:
	inc		r9d				; next square clockwise
	and		r9d, 3
	movzx		r10d, byte [abs dir_idx + r9]
	cmp		byte [rdi + VIEW_CELLS + r10], CELL_EMPTY
	je		emit
	inc		r9d				; next square clockwise
	and		r9d, 3
	movzx		r10d, byte [abs dir_idx + r9]
	cmp		byte [rdi + VIEW_CELLS + r10], CELL_EMPTY
	je		emit
	inc		r9d				; next square clockwise
	and		r9d, 3
	movzx		r10d, byte [abs dir_idx + r9]
	cmp		byte [rdi + VIEW_CELLS + r10], CELL_EMPTY
	je		emit
	inc		r9d				; the fourth square is the empty one
	and		r9d, 3
emit:
	cmp		dword [rdi + VIEW_TICK], 0
	jb		emit_long
	mov		byte [abs CELLMEM_BASE + 1], 2
	jmp		emit_store
emit_long:
	mov		byte [abs CELLMEM_BASE + 1], 8
emit_store:
	mov		[abs CELLMEM_BASE + 0], r9b
	mov		[abs CELLMEM_BASE + 4], ecx
	lea		eax, [r9 + ACT_SPLIT]
	ret
threat:
	mov		byte [abs CELLMEM_BASE + 1], 0	; a walker stops here
	cmp		esi, 5
	jb		rest
	cmp		dword [rdi + VIEW_TICK], 2980
	jae		EXIT_ADDR			; late: split anyway (al = gate 1's split)
rest:
	mov		al, ACT_REST
	ret
setlock:
	mov		[abs CELLMEM_BASE + 3], al
	movzx		ecx, al
	and		ecx, 3
	mov		cl, [abs lock_off + rcx]
	mov		[abs CELLMEM_BASE + 2], cl
	ret
boxed:
	cmp		esi, 6
	jb		rest
	movdqu		xmm1, [rdi + VIEW_CELLS]	; view idx 0..15
	movdqu		xmm2, [rdi + VIEW_CELLS + 9]	; view idx 9..24
	pcmpeqb		xmm1, [kTwoLo]
	pcmpeqb		xmm2, [kTwoHi]
	por		xmm1, xmm2
	pmovmskb	edx, xmm1
	test		edx, edx
	jnz		fallback			; enemy in the 5x5
	movdqu		xmm1, [rdi + VIEW_CELLS + 6]	; view idx 6..21
	pcmpeqb		xmm1, [kZero]
	pmovmskb	edx, xmm1			; bit (idx - 6): empty
	cmp		byte [rdi + VIEW_CELLS + 7], CELL_FRIEND
	jne		.s_up
	test		edx, 0x0005
	jnz		feed_up
	cmp		byte [rdi + VIEW_CELLS + 2], CELL_EMPTY
	je		feed_up
.s_up:
	cmp		byte [rdi + VIEW_CELLS + 13], CELL_FRIEND
	jne		.s_right
	test		edx, 0x1104
	jnz		feed_right
.s_right:
	cmp		byte [rdi + VIEW_CELLS + 17], CELL_FRIEND
	jne		.s_down
	test		edx, 0x1400
	jnz		feed_down
	cmp		byte [rdi + VIEW_CELLS + 22], CELL_EMPTY
	je		feed_down
.s_down:
	cmp		byte [rdi + VIEW_CELLS + 11], CELL_FRIEND
	jne		.s_left
	test		edx, 0x0411
	jnz		feed_left
.s_left:
fallback:
	cmp		esi, 16
	jb		rest
	lea		r9d, [rsi - 4]		; limit: poorest friend <= e - 4 ...
	mov		r10d, 46
	cmp		esi, 47
	cmovae		r9d, r10d			; ... or <= 46 for a capped donor
	mov		r8d, 255			; poorest friend energy so far
	mov		eax, ACT_REST
	cmp		byte [rdi + VIEW_CELLS + 7], CELL_FRIEND	; up
	jne		.n_up
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 7]
	cmp		ecx, r8d
	jae		.n_up
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_UP
.n_up:
	cmp		byte [rdi + VIEW_CELLS + 13], CELL_FRIEND	; right
	jne		.n_right
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 13]
	cmp		ecx, r8d
	jae		.n_right
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_RIGHT
.n_right:
	cmp		byte [rdi + VIEW_CELLS + 17], CELL_FRIEND	; down
	jne		.n_down
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 17]
	cmp		ecx, r8d
	jae		.n_down
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_DOWN
.n_down:
	cmp		byte [rdi + VIEW_CELLS + 11], CELL_FRIEND	; left
	jne		.n_left
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 11]
	cmp		ecx, r8d
	jae		.n_left
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_LEFT
.n_left:
	cmp		r8d, r9d
	ja		rest				; no friend (255), or the poorest is above the limit
	ret					; al = ACT_FEED + direction

feed_up:
	mov		al, ACT_FEED + DIR_UP
	ret
feed_right:
	mov		al, ACT_FEED + DIR_RIGHT
	ret
feed_down:
	mov		al, ACT_FEED + DIR_DOWN
	ret
feed_left:
	mov		al, ACT_FEED + DIR_LEFT
	ret

; ---- constants (legacy-SSE memory operands must be 16-byte aligned)
	align 16
kEnemy:	db 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0xff, 0xff, 0xff, 0xff	; 2 at UP/LEFT/RIGHT/DOWN lanes (window idx 7..22)
kRefill:	db 0x02, 0x00, 0x02, 0xff, 0x02, 0x00, 0xff, 0x00, 0x02, 0xff, 0x02, 0x00, 0x02, 0xff, 0xff, 0xff	; window idx 6..21: 0 at neighbours, 2 at 6/8/10/14/16/18
kZero:	times 16 db 0
kTwoLo:	db 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02	; idx 0..15, self (lane 12) excluded
kTwoHi:	db 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02	; idx 9..24, self (lane 3) excluded
dir_idx:	db 7, 13, 17, 11	; view index of the neighbour UP, RIGHT, DOWN, LEFT
lock_off:	db 15, 21, 25, 19	; stored-bite offset for UP, RIGHT, DOWN, LEFT

